51	    /**
52	     * 授权：当前授权仍有效时返回原代次；撤回后或首次授权生成下一代（从 1 开始递增）。
53	     */
54	    @Transactional
55	    public GrantResponse grant(GrantRequest request) {
56	        String fingerprint = OP_GRANT + "|" + request.subjectKey() + "|" + request.purpose();
57	        Optional<IdempotencyRow> replayed = checkReplay(request.requestId(), fingerprint);
58	        if (replayed.isPresent()) {
59	            return readSnapshot(replayed.get().responseBody(), GrantResponse.class);
60	        }
61	
62	        Optional<ConsentRepository.GrantRow> latest =
63	                consentRepository.findLatestGrant(request.subjectKey(), request.purpose());
64	        GrantResponse response;
65	        if (latest.isPresent() && latest.get().status() == GrantStatus.ACTIVE) {
66	            response = new GrantResponse(request.subjectKey(), request.purpose(),
67	                    latest.get().epoch(), GrantStatus.ACTIVE);
68	        } else {
69	            int nextEpoch = latest.map(row -> row.epoch() + 1).orElse(1);
70	            try {
71	                consentRepository.insertGrant(request.subjectKey(), request.purpose(), nextEpoch, request.requestId());
72	            } catch (DuplicateKeyException concurrent) {
73	                // 并发授权同一代次：以已提交的行为准
74	                ConsentRepository.GrantRow committed =
75	                        consentRepository.findGrant(request.subjectKey(), request.purpose(), nextEpoch)
76	                                .orElseThrow(() -> concurrent);
77	                response = new GrantResponse(committed.subjectKey(), committed.purpose(),
78	                        committed.epoch(), committed.status());
79	                storeSuccess(request.requestId(), OP_GRANT, fingerprint, response);
80	                return response;
81	            }
82	            response = new GrantResponse(request.subjectKey(), request.purpose(), nextEpoch, GrantStatus.ACTIVE);
83	        }
84	        storeSuccess(request.requestId(), OP_GRANT, fingerprint, response);
85	        return response;
86	    }
87	
88	    /**
89	     * 写入：仅当前有效代次可写；同代同 recordKey 同 payload 去重返回原记录，不同 payload 返回 409。
90	     */
91	    @Transactional
92	    public RecordResponse write(RecordWriteRequest request) {
93	        String fingerprint = OP_WRITE + "|" + request.subjectKey() + "|" + request.purpose()
94	                + "|" + request.recordKey() + "|" + request.payload();
95	        Optional<IdempotencyRow> replayed = checkReplay(request.requestId(), fingerprint);
96	        if (replayed.isPresent()) {
97	            RecordResponse snapshot = readSnapshot(replayed.get().responseBody(), RecordResponse.class);
98	            requireGrantActive(snapshot.subjectKey(), snapshot.purpose(), snapshot.epoch());
99	            return snapshot;
100	        }
101	
102	        ConsentRepository.GrantRow latest = consentRepository
103	                .findLatestGrant(request.subjectKey(), request.purpose())
104	                .orElseThrow(() -> ApiException.notFound(CODE_GRANT_NOT_FOUND, "授权不存在"));
105	        requireGrantActive(latest.subjectKey(), latest.purpose(), latest.epoch());
106	
107	        Optional<ConsentRepository.RecordRow> existing = consentRepository.findRecord(
108	                request.subjectKey(), request.purpose(), latest.epoch(), request.recordKey());
109	        if (existing.isPresent()) {
110	            if (!existing.get().payload().equals(request.payload())) {
111	                throw ApiException.conflict(CODE_RECORD_PAYLOAD_CONFLICT, "相同 recordKey 已存在不同内容");
112	            }
113	            RecordResponse response = toResponse(existing.get());
114	            storeSuccess(request.requestId(), OP_WRITE, fingerprint, response);
115	            return response;
116	        }
117	
118	        try {
119	            consentRepository.insertRecord(request.subjectKey(), request.purpose(), latest.epoch(),
120	                    request.recordKey(), request.payload(), request.requestId());
121	        } catch (DuplicateKeyException concurrent) {
122	            // 并发写入同一 recordKey：以已提交的记录为准
123	            ConsentRepository.RecordRow committed = consentRepository.findRecord(
124	                            request.subjectKey(), request.purpose(), latest.epoch(), request.recordKey())
125	                    .orElseThrow(() -> concurrent);
126	            if (!committed.payload().equals(request.payload())) {
127	                throw ApiException.conflict(CODE_RECORD_PAYLOAD_CONFLICT, "相同 recordKey 已存在不同内容");
128	            }
129	            RecordResponse response = toResponse(committed);
130	            storeSuccess(request.requestId(), OP_WRITE, fingerprint, response);
131	            return response;
132	        }
133	
134	        RecordResponse response = new RecordResponse(request.subjectKey(), request.purpose(),
135	                latest.epoch(), request.recordKey(), request.payload());
136	        storeSuccess(request.requestId(), OP_WRITE, fingerprint, response);
137	        return response;
138	    }
139	
140	    /**
141	     * 撤回：指定代次只允许从有效变为已撤回；撤回提交后旧代查询立即返回 410，写入被拒绝。
142	     */
143	    @Transactional
144	    public GrantResponse revoke(RevokeRequest request) {
145	        String fingerprint = OP_REVOKE + "|" + request.subjectKey() + "|" + request.purpose() + "|" + request.epoch();
146	        Optional<IdempotencyRow> replayed = checkReplay(request.requestId(), fingerprint);
147	        if (replayed.isPresent()) {
148	            return readSnapshot(replayed.get().responseBody(), GrantResponse.class);
149	        }
150	
151	        consentRepository.findGrant(request.subjectKey(), request.purpose(), request.epoch())
152	                .orElseThrow(() -> ApiException.notFound(CODE_GRANT_NOT_FOUND, "授权代次不存在"));
153	        boolean revoked = consentRepository.revokeGrant(request.subjectKey(), request.purpose(), request.epoch());
154	        if (!revoked) {
155	            throw ApiException.conflict(CODE_GRANT_ALREADY_REVOKED, "授权代次已撤回");
156	        }
157	        GrantResponse response = new GrantResponse(request.subjectKey(), request.purpose(),
158	                request.epoch(), GrantStatus.REVOKED);
159	        storeSuccess(request.requestId(), OP_REVOKE, fingerprint, response);
160	        return response;
161	    }
162	
163	    /**
164	     * 查询：仅当前有效代次可查；撤回后返回 410，记录不存在返回 404。
165	     */
166	    @Transactional(readOnly = true)
167	    public RecordResponse read(String subjectKey, Purpose purpose, String recordKey) {
168	        ConsentRepository.GrantRow latest = consentRepository.findLatestGrant(subjectKey, purpose)
169	                .orElseThrow(() -> ApiException.notFound(CODE_GRANT_NOT_FOUND, "授权不存在"));
170	        requireGrantActive(latest.subjectKey(), latest.purpose(), latest.epoch());
171	        return consentRepository.findRecord(subjectKey, purpose, latest.epoch(), recordKey)
172	                .map(this::toResponse)
173	                .orElseThrow(() -> ApiException.notFound(CODE_RECORD_NOT_FOUND, "记录不存在"));
174	    }
175	
176	    private void requireGrantActive(String subjectKey, Purpose purpose, int epoch) {
177	        ConsentRepository.GrantRow grant = consentRepository.findGrant(subjectKey, purpose, epoch)
178	                .orElseThrow(() -> ApiException.notFound(CODE_GRANT_NOT_FOUND, "授权代次不存在"));
179	        if (grant.status() == GrantStatus.REVOKED) {
180	            throw ApiException.gone(CODE_CONSENT_REVOKED, "授权已撤回");
181	        }
182	    }
183	
184	    /**
185	     * 幂等重放检查：命中且参数一致返回原快照；参数不一致返回 409。
186	     */
187	    private Optional<IdempotencyRow> checkReplay(String requestId, String fingerprint) {
188	        Optional<IdempotencyRow> row = idempotencyRepository.find(requestId);
189	        if (row.isPresent() && !row.get().paramsFingerprint().equals(fingerprint)) {
190	            throw ApiException.conflict(CODE_REQUEST_ID_CONFLICT, "同一 requestId 参数不一致");
191	        }
192	        return row;
193	    }
194	
195	    private void storeSuccess(String requestId, String operation, String fingerprint, Object response) {
196	        try {
197	            idempotencyRepository.insert(requestId, operation, fingerprint, writeSnapshot(response));
198	        } catch (DuplicateKeyException concurrent) {
199	            // 并发同 requestId：校验已提交快照参数一致，否则视为冲突
200	            IdempotencyRow committed = idempotencyRepository.find(requestId)
201	                    .orElseThrow(() -> concurrent);
202	            if (!committed.paramsFingerprint().equals(fingerprint)) {
203	                throw ApiException.conflict(CODE_REQUEST_ID_CONFLICT, "同一 requestId 参数不一致");
204	            }
205	        }
206	    }
207	
208	    private RecordResponse toResponse(ConsentRepository.RecordRow row) {
209	        return new RecordResponse(row.subjectKey(), row.purpose(), row.epoch(), row.recordKey(), row.payload());
210	    }
211	
212	    private String writeSnapshot(Object response) {
213	        try {
214	            return objectMapper.writeValueAsString(response);
215	        } catch (JsonProcessingException e) {
216	            throw new IllegalStateException("响应快照序列化失败", e);
217	        }
218	    }
219	
220	    private <T> T readSnapshot(String body, Class<T> type) {
221	        try {
222	            return objectMapper.readValue(body, type);
223	        } catch (JsonProcessingException e) {
224	            throw new IllegalStateException("响应快照反序列化失败", e);
225	        }
226	    }
