        migrate("m-1", "subj-a", "RESEARCH", "ap-sg", "rec-1", "rec-2").andExpect(status().isOk());

        // 迁移已提交：钉住旧 epoch 的查询整次 410
        crossQuery("q-1", "\"eu-west\",\"ap-sg\"", objectRef("subj-a", "RESEARCH", "rec-1", 1))
